// ---- content/b-frac.js ----
// Школьная база · «Обыкновенные дроби» (5–6 класс) + олимпиадные задачи: египетские дроби, телескопические суммы.
(function () {
  function fr(a, b) { return '<span class="fr"><span>' + a + '</span><span>' + b + '</span></span>'; }
  function mix(w, a, b) { return w + fr(a, b); } // смешанное число

  MM.addTopic({
    id: 'b-frac',
    sec: 'base',
    title: 'Обыкновенные дроби',
    blurb: `Основное свойство дроби, сокращение и сравнение, четыре действия, дробь от числа и число по дроби. Без уверенной работы с дробями не решается ни одна алгебраическая задача.`,

    lessons: [
      { id: 'fr-l1', title: 'Дроби: сокращение и сравнение', mins: 10, html: `
<p>Дробь <span class="m">${fr('a', 'b')}</span> — это <span class="m">a</span> частей из <span class="m">b</span> равных. Главное свойство: числитель и знаменатель можно умножить или разделить на одно и то же число, и дробь не изменится: <span class="m">${fr('a', 'b')} = ${fr('ac', 'bc')}</span>.</p>
<div class="box"><div class="box-h">Запомни</div><ul>
<li><b>Сокращение</b> — делим на НОД числителя и знаменателя: <span class="m">${fr('24', '36')} = ${fr('2', '3')}</span> (сократили на 12).</li>
<li><b>Общий знаменатель</b> — НОК знаменателей: <span class="m">${fr('5', '6')}</span> и <span class="m">${fr('7', '8')}</span> — это <span class="m">${fr('20', '24')}</span> и <span class="m">${fr('21', '24')}</span>.</li>
<li><b>Сравнение крест-накрест:</b> при положительных знаменателях <span class="m">${fr('a', 'b')} < ${fr('c', 'd')}</span> ровно тогда, когда <span class="m">ad < bc</span>. Например, <span class="m">${fr('7', '9')} < ${fr('4', '5')}</span>, потому что <span class="m">35 < 36</span>.</li>
<li><b>Смешанное число:</b> <span class="m">${mix(2, 3, 5)} = ${fr('13', '5')}</span>.</li>
</ul></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Чтобы сравнить дроби, близкие к 1, сравни их «недостачи»: <span class="m">${fr('99', '100')}</span> и <span class="m">${fr('100', '101')}</span> отличаются от 1 на <span class="m">${fr('1', '100')}</span> и <span class="m">${fr('1', '101')}</span>, поэтому вторая дробь больше.</p></div>` },

      { id: 'fr-l2', title: 'Действия с дробями', mins: 12, html: `
<div class="box"><div class="box-h">Четыре действия</div><ul>
<li>Сложение и вычитание — через общий знаменатель: <span class="m">${fr('1', '6')} + ${fr('3', '4')} = ${fr('2', '12')} + ${fr('9', '12')} = ${fr('11', '12')}</span>.</li>
<li>Умножение: <span class="m">${fr('a', 'b')} · ${fr('c', 'd')} = ${fr('ac', 'bd')}</span>. Сокращай <b>до</b> умножения: <span class="m">${fr('6', '35')} · ${fr('14', '9')} = ${fr('2 · 2', '5 · 3')} = ${fr('4', '15')}</span>.</li>
<li>Деление — умножение на перевёрнутую дробь: <span class="m">${fr('a', 'b')} : ${fr('c', 'd')} = ${fr('a', 'b')} · ${fr('d', 'c')}</span>.</li>
</ul></div>
<h3>Дробь от числа и число по дроби</h3>
<p><span class="m">${fr('3', '4')}</span> от 20 — это <span class="m">20 · ${fr('3', '4')} = 15</span>. Если <span class="m">${fr('2', '3')}</span> числа равны 12, то само число равно <span class="m">12 : ${fr('2', '3')} = 18</span>.</p>
<div class="ex"><div class="ex-h">Пример</div>
<p>Вычислите <span class="m">(${fr('5', '6')} − ${fr('1', '4')}) : ${fr('7', '9')}</span>.</p>
<p><b>Решение.</b> <span class="m">${fr('5', '6')} − ${fr('1', '4')} = ${fr('10 − 3', '12')} = ${fr('7', '12')}</span>; <span class="m">${fr('7', '12')} · ${fr('9', '7')} = ${fr('9', '12')} = ${fr('3', '4')}</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>В длинных произведениях дробей ищи сокращения «по цепочке»: числитель одной дроби сокращается со знаменателем соседней, и от огромного произведения остаётся пара чисел.</p></div>` }
    ],

    problems: [
      { id: 'fr-01', lvl: 1, r: 800, type: 'num', q: `Сократите дробь ${fr('36', '48')}. Ответ запишите несократимой дробью.`, a: ['3/4', '0.75'],
        hints: [`НОД(36, 48) = 12.`], sol: `${fr('36', '48')} = ${fr('36 : 12', '48 : 12')} = ${fr('3', '4')}.` },
      { id: 'fr-02', lvl: 1, r: 840, type: 'num', q: `Вычислите ${fr('2', '3')} + ${fr('1', '4')}. Ответ запишите несократимой дробью.`, a: ['11/12'],
        hints: [`Общий знаменатель 12.`], sol: `${fr('8', '12')} + ${fr('3', '12')} = ${fr('11', '12')}.` },
      { id: 'fr-03', lvl: 1, r: 880, type: 'num', q: `Найдите ${fr('3', '5')} от 40.`, a: ['24'],
        hints: [`Раздели 40 на 5 и умножь на 3.`], sol: `40 : 5 · 3 = 24.` },
      { id: 'fr-04', lvl: 1, r: 920, type: 'choice', q: `Какая из дробей наибольшая?`, opts: ['5/8', '7/12', '3/5', '11/20'], a: 0,
        hints: [`Приведи к общему знаменателю 120 или сравни крест-накрест.`],
        sol: `С общим знаменателем 120: ${fr('75', '120')}, ${fr('70', '120')}, ${fr('72', '120')}, ${fr('66', '120')}. Наибольшая — ${fr('5', '8')}.` },
      { id: 'fr-05', lvl: 1, r: 960, type: 'num', q: `Вычислите ${fr('3', '4')} : ${fr('9', '16')}. Ответ запишите несократимой дробью.`, a: ['4/3'],
        hints: [`Деление на дробь — умножение на перевёрнутую дробь.`], sol: `${fr('3', '4')} · ${fr('16', '9')} = ${fr('48', '36')} = ${fr('4', '3')}.` },

      { id: 'fr-06', lvl: 2, r: 1050, type: 'num', q: `Вычислите ${mix(2, 1, 3)} · ${mix(1, 2, 7)}.`, a: ['3'],
        hints: [`Переведи смешанные числа в неправильные дроби.`], sol: `${fr('7', '3')} · ${fr('9', '7')} = ${fr('9', '3')} = 3.` },
      { id: 'fr-07', lvl: 2, r: 1100, type: 'num', q: `Ученик прочитал ${fr('2', '5')} книги, и ему осталось прочитать 90 страниц. Сколько страниц в книге?`, a: ['150'],
        hints: [`90 страниц — это ${fr('3', '5')} книги.`], sol: `Осталось ${fr('3', '5')} книги, это 90 страниц. Вся книга: 90 : ${fr('3', '5')} = 150 страниц.` },
      { id: 'fr-08', lvl: 2, r: 1150, type: 'num', q: `Решите уравнение ${fr('5', '6')} · x = ${fr('10', '9')}. Ответ запишите несократимой дробью.`, a: ['4/3'],
        hints: [`x = ${fr('10', '9')} : ${fr('5', '6')}.`], sol: `x = ${fr('10', '9')} · ${fr('6', '5')} = ${fr('60', '45')} = ${fr('4', '3')}.` },
      { id: 'fr-09', lvl: 2, r: 1200, type: 'num', q: `Найдите сумму ${fr('1', '2')} + ${fr('1', '4')} + ${fr('1', '8')} + ${fr('1', '16')} + ${fr('1', '32')}. Ответ запишите несократимой дробью.`, a: ['31/32'],
        hints: [`Сколько не хватает до 1 после каждого шага?`], sol: `После каждого слагаемого до 1 не хватает ровно последнего слагаемого: в конце не хватает ${fr('1', '32')}. Сумма ${fr('31', '32')}.` },
      { id: 'fr-10', lvl: 2, r: 1250, type: 'num', q: `Какую часть часа составляют 25 минут? Ответ запишите несократимой дробью.`, a: ['5/12'],
        hints: [`В часе 60 минут.`], sol: `${fr('25', '60')} = ${fr('5', '12')}.` },

      { id: 'fr-11', lvl: 3, r: 1350, type: 'num', q: `Вычислите (1 − ${fr('1', '2')})(1 − ${fr('1', '3')})(1 − ${fr('1', '4')}) … (1 − ${fr('1', '10')}). Ответ запишите несократимой дробью.`, a: ['1/10', '0.1'],
        hints: [`Каждая скобка — дробь вида (n − 1)/n.`], sol: `${fr('1', '2')} · ${fr('2', '3')} · ${fr('3', '4')} · … · ${fr('9', '10')}: числитель каждой дроби сокращается со знаменателем предыдущей, остаётся ${fr('1', '10')}.` },
      { id: 'fr-12', lvl: 3, r: 1400, type: 'num', q: `Числитель дроби на 5 меньше знаменателя. Если к числителю и знаменателю прибавить по 3, получится ${fr('2', '3')}. Найдите исходную дробь.`, a: ['7/12'],
        hints: [`Пусть знаменатель d, тогда числитель d − 5.`, `(d − 2)/(d + 3) = 2/3.`], sol: `${fr('d − 2', 'd + 3')} = ${fr('2', '3')}, откуда 3d − 6 = 2d + 6, d = 12. Дробь ${fr('7', '12')}. Проверка: ${fr('10', '15')} = ${fr('2', '3')}.` },
      { id: 'fr-13', lvl: 3, r: 1450, type: 'num', q: `Найдите наименьшее натуральное число, которое при умножении и на ${fr('3', '8')}, и на ${fr('5', '12')} даёт целые числа.`, a: ['24'],
        hints: [`n · 3/8 целое ⇔ 8 делит n (3 и 8 взаимно просты).`], sol: `n · ${fr('3', '8')} целое ⇔ 8 <span class="dv">∣</span> n; n · ${fr('5', '12')} целое ⇔ 12 <span class="dv">∣</span> n. Наименьшее такое n — НОК(8, 12) = 24.` },
      { id: 'fr-14', lvl: 3, r: 1500, type: 'num', q: `Сколько существует несократимых дробей со знаменателем 30, которые больше 0 и меньше 1?`, a: ['8'],
        hints: [`Нужны числители от 1 до 29, взаимно простые с 30 = 2 · 3 · 5.`], sol: `Подходят числители 1, 7, 11, 13, 17, 19, 23, 29 — восемь.` },
      { id: 'fr-15', lvl: 3, r: 1550, type: 'num', q: `Какая из дробей ${fr('2', '3')}, ${fr('5', '7')}, ${fr('7', '10')}, ${fr('9', '13')} наибольшая? Запишите её в ответ.`, a: ['5/7'],
        hints: [`Сравни, сколько каждой дроби не хватает до 1: 1/3, 2/7, 3/10, 4/13.`], sol: `До 1 не хватает ${fr('1', '3')}, ${fr('2', '7')}, ${fr('3', '10')}, ${fr('4', '13')} ≈ 0,333; 0,286; 0,3; 0,308. Меньше всего не хватает у ${fr('5', '7')} — она наибольшая.` }
    ]
  });

  MM.addDeep('b-frac', {
    lessons: [
      { id: 'fr-l3', title: 'Египетские дроби и телескопические суммы', mins: 14, html: `
<h3>Телескопические суммы</h3>
<p>Главное тождество: <span class="m">${fr('1', 'n(n + 1)')} = ${fr('1', 'n')} − ${fr('1', 'n + 1')}</span>. Поэтому в сумме соседние слагаемые уничтожаются, как звенья складной подзорной трубы:</p>
<p class="calc"><span class="m">${fr('1', '1 · 2')} + ${fr('1', '2 · 3')} + ${fr('1', '3 · 4')} + ${fr('1', '4 · 5')} = (1 − ${fr('1', '2')}) + (${fr('1', '2')} − ${fr('1', '3')}) + … + (${fr('1', '4')} − ${fr('1', '5')}) = 1 − ${fr('1', '5')} = ${fr('4', '5')}</span>.</p>
<p>Если множители отличаются на <span class="m">k</span>: <span class="m">${fr('1', 'n(n + k)')} = ${fr('1', 'k')}(${fr('1', 'n')} − ${fr('1', 'n + k')})</span>.</p>
<h3>Египетские дроби</h3>
<p>Древние египтяне записывали дроби суммами <b>различных</b> дробей с числителем 1. Полезное тождество: <span class="m">${fr('1', 'n')} = ${fr('1', 'n + 1')} + ${fr('1', 'n(n + 1)')}</span>. Например, <span class="m">${fr('1', '2')} = ${fr('1', '3')} + ${fr('1', '6')}</span> и <span class="m">1 = ${fr('1', '2')} + ${fr('1', '3')} + ${fr('1', '6')}</span>.</p>
<div class="ex"><div class="ex-h">Жадный способ</div>
<p>Запишем <span class="m">${fr('4', '13')}</span>. Берём самую большую дробь вида <span class="m">${fr('1', 'n')}</span>, не превосходящую <span class="m">${fr('4', '13')}</span>: это <span class="m">${fr('1', '4')}</span>. Остаток <span class="m">${fr('4', '13')} − ${fr('1', '4')} = ${fr('3', '52')}</span>. Дальше <span class="m">${fr('1', '18')}</span>, остаток <span class="m">${fr('3', '52')} − ${fr('1', '18')} = ${fr('1', '468')}</span>. Итог: <span class="m">${fr('4', '13')} = ${fr('1', '4')} + ${fr('1', '18')} + ${fr('1', '468')}</span>.</p></div>
<div class="trick"><div class="trick-h">Олимпиадный приём</div>
<p>Видишь сумму дробей с произведениями в знаменателях — разложи каждую дробь в разность. Видишь уравнение <span class="m">${fr('1', 'x')} + ${fr('1', 'y')} = ${fr('1', 'n')}</span> — приведи его к виду <span class="m">(x − n)(y − n) = n<sup>2</sup></span> и перебери делители.</p></div>` }
    ],
    problems: [
      { id: 'fr-16', lvl: 4, r: 1700, type: 'num', q: `Вычислите <span class="nw">${fr('1', '1 · 2')} + ${fr('1', '2 · 3')} + … + ${fr('1', '99 · 100')}</span>. Ответ запишите несократимой дробью или десятичной дробью.`, a: ['99/100', '0.99'],
        hints: [`${fr('1', 'n(n + 1)')} = ${fr('1', 'n')} − ${fr('1', 'n + 1')}.`], sol: `Сумма равна 1 − ${fr('1', '100')} = ${fr('99', '100')}.` },
      { id: 'fr-17', lvl: 4, r: 1800, type: 'num', q: `Вычислите <span class="nw">${fr('1', '1 · 3')} + ${fr('1', '3 · 5')} + … + ${fr('1', '99 · 101')}</span>. Ответ запишите несократимой дробью.`, a: ['50/101'],
        hints: [`${fr('1', 'n(n + 2)')} = ${fr('1', '2')}(${fr('1', 'n')} − ${fr('1', 'n + 2')}).`], sol: `Сумма равна ${fr('1', '2')}(1 − ${fr('1', '101')}) = ${fr('1', '2')} · ${fr('100', '101')} = ${fr('50', '101')}.` },
      { id: 'fr-18', lvl: 4, r: 1900, type: 'num', q: `Сколько существует пар натуральных чисел x < y, для которых ${fr('1', 'x')} + ${fr('1', 'y')} = ${fr('1', '6')}?`, a: ['4'],
        hints: [`Умножь на 6xy: 6y + 6x = xy.`, `(x − 6)(y − 6) = 36.`],
        sol: `Из 6x + 6y = xy получаем (x − 6)(y − 6) = 36. Оба множителя положительны (иначе x или y не больше 6, и ${fr('1', 'x')} + ${fr('1', 'y')} > ${fr('1', '6')}). При x < y: 1 · 36, 2 · 18, 3 · 12, 4 · 9 — пары (7, 42), (8, 24), (9, 18), (10, 15). Ответ: 4.` },
      { id: 'fr-19', lvl: 5, r: 2000, type: 'num', q: `Вычислите <span class="nw">${fr('1', '1 · 2 · 3')} + ${fr('1', '2 · 3 · 4')} + … + ${fr('1', '8 · 9 · 10')}</span>. Ответ запишите несократимой дробью.`, a: ['11/45'],
        hints: [`${fr('1', 'n(n + 1)(n + 2)')} = ${fr('1', '2')}(${fr('1', 'n(n + 1)')} − ${fr('1', '(n + 1)(n + 2)')}).`],
        sol: `По тождеству сумма телескопируется: ${fr('1', '2')}(${fr('1', '1 · 2')} − ${fr('1', '9 · 10')}) = ${fr('1', '2')} · (${fr('1', '2')} − ${fr('1', '90')}) = ${fr('1', '2')} · ${fr('44', '90')} = ${fr('11', '45')}.` },
      { id: 'fr-20', lvl: 5, r: 2100, type: 'proof', q: `Докажите, что число 1 можно представить в виде суммы 2026 различных дробей с числителем 1.`,
        hints: [`Начни с 1 = ${fr('1', '2')} + ${fr('1', '3')} + ${fr('1', '6')}.`, `${fr('1', 'k')} = ${fr('1', '2k')} + ${fr('1', '3k')} + ${fr('1', '6k')} — это добавляет два слагаемых.`, `Чтобы получить чётное количество, один раз используй ${fr('1', 'k')} = ${fr('1', 'k + 1')} + ${fr('1', 'k(k + 1)')}.`],
        sol: `Начнём с 1 = ${fr('1', '2')} + ${fr('1', '3')} + ${fr('1', '6')} и заменим ${fr('1', '6')} = ${fr('1', '7')} + ${fr('1', '42')}: получилось 4 различных слагаемых. Дальше будем повторять шаг: самую маленькую дробь ${fr('1', 'm')} (с наибольшим знаменателем m) заменим на ${fr('1', '2m')} + ${fr('1', '3m')} + ${fr('1', '6m')} — сумма не меняется, так как ${fr('1', '2')} + ${fr('1', '3')} + ${fr('1', '6')} = 1. Новые знаменатели больше всех прежних (они больше m), поэтому все дроби остаются различными, а слагаемых становится на 2 больше. После 1011 шагов получим 4 + 2 · 1011 = 2026 слагаемых.`,
        rubric: [[2, `Начальное представление с чётным числом различных слагаемых`], [3, `Шаг, сохраняющий сумму и различие знаменателей`], [2, `Подсчёт: получается ровно 2026 слагаемых`]] },
      { id: 'fr-21', lvl: 5, r: 2200, type: 'proof', q: `Докажите, что любую дробь ${fr('a', 'b')}, где 0 < a < b — натуральные, можно представить в виде суммы различных дробей с числителем 1.`,
        hints: [`Жадный способ: возьми наименьшее n с ${fr('1', 'n')} ≤ ${fr('a', 'b')} и вычти.`, `Числитель остатка ${fr('an − b', 'bn')} меньше a. Почему?`, `Остаток меньше ${fr('1', 'n')}, поэтому следующая дробь будет меньше.`],
        sol: `Возьмём наименьшее n, для которого ${fr('1', 'n')} ≤ ${fr('a', 'b')}. Если равенство — готово. Иначе ${fr('1', 'n − 1')} > ${fr('a', 'b')}, то есть a(n − 1) < b, и остаток ${fr('a', 'b')} − ${fr('1', 'n')} = ${fr('an − b', 'bn')} имеет числитель an − b < a (и он положителен). Кроме того, остаток меньше ${fr('1', 'n − 1')} − ${fr('1', 'n')} = ${fr('1', 'n(n − 1)')} ≤ ${fr('1', 'n')}, поэтому следующая выбранная дробь будет меньше ${fr('1', 'n')}, и знаменатели получатся различными. Числитель с каждым шагом уменьшается хотя бы на 1, поэтому процесс закончится не больше чем через a шагов, когда остаток станет дробью с числителем 1 (числитель после сокращения может стать только меньше).`,
        rubric: [[2, `Описан жадный шаг`], [2, `Доказано, что числитель остатка уменьшается`], [2, `Доказано, что знаменатели получаются различными`], [1, `Вывод: процесс конечен`]] }
    ]
  });
})();

